import { ShoppingCart, CheckSquare, Wallet } from 'lucide-react';
import { TabsNav } from '@/components/TabsNav';
import { ShoppingClient } from '@/components/ShoppingClient';
import { TodoClient } from '@/components/TodoClient';
import { FinanceClient } from '@/components/FinanceClient';

// Using searchParams to fetch different data depending on the tab directly in Server Component.
// This preserves the SSR without useEffect architecture exactly as requested.
export default async function Home({ searchParams }: { searchParams: { tab?: string } }) {
  // Await searchParams in Next 15
  const params = await searchParams;
  const currentTab = params.tab || 'dashboard';

  let shopping = [];
  let todos = [];
  let finances = [];

  // Parallel fetching, only fetching what is needed for current view
  const fetchPromises = [];
  
  if (currentTab === 'dashboard' || currentTab === 'shopping') {
    fetchPromises.push(
      fetch('http://localhost:3000/api/shopping', { cache: 'no-store' })
        .then(r => r.json())
        .then(d => { shopping = d; })
        .catch(() => null)
    );
  }
  
  if (currentTab === 'dashboard' || currentTab === 'todos') {
    fetchPromises.push(
      fetch('http://localhost:3000/api/todos', { cache: 'no-store' })
        .then(r => r.json())
        .then(d => { todos = d; })
        .catch(() => null)
    );
  }
  
  if (currentTab === 'dashboard' || currentTab === 'finance') {
    fetchPromises.push(
      fetch('http://localhost:3000/api/finances', { cache: 'no-store' })
        .then(r => r.json())
        .then(d => { finances = d; })
        .catch(() => null)
    );
  }

  await Promise.all(fetchPromises);

  return (
    <div className="flex flex-col min-h-screen pt-16 px-6 max-w-6xl mx-auto w-full animate-fade-in relative pb-20">
      <header className="mb-10 text-center md:text-left flex flex-col items-center md:items-start">
        <h1 className="text-[2.5rem] font-[800] mb-2 bg-gradient-to-r from-blue-500 to-violet-500 bg-clip-text text-transparent inline-block tracking-tight m-0">
          Willkommen Zuhause! 🏠
        </h1>
        <p className="text-slate-600 text-lg">Hier ist die aktuelle Übersicht für eure WG.</p>
      </header>

      <TabsNav currentTab={currentTab} />

      <main className="mt-6 flex justify-center w-full">
        {currentTab === 'dashboard' && <DashboardView shopping={shopping} todos={todos} finances={finances} />}
        {currentTab === 'shopping' && <ShoppingClient initialItems={shopping} />}
        {currentTab === 'todos' && <TodoClient initialTodos={todos} />}
        {currentTab === 'finance' && <FinanceClient initialExpenses={finances} />}
      </main>
    </div>
  );
}

function DashboardView({ shopping, todos, finances }: any) {
  const missingItemsCount = shopping?.filter((i: any) => !i.checked).length || 0;
  const nextTodo = todos?.find((i: any) => !i.completed);
  const financesStatusText = "Dieser Monat sieht gut aus! Keine offenen Schulden ermittelt.";

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fade-in w-full">
      <div className="glass-panel p-8 flex flex-col gap-4">
        <div className="flex items-center gap-4 text-blue-500">
          <ShoppingCart size={32} />
          <h2 className="text-2xl font-semibold m-0 text-slate-900 border-none">Einkauf</h2>
        </div>
        <p className="text-slate-600 leading-relaxed">
          {missingItemsCount === 0 
            ? "Alles besorgt!"
            : `${missingItemsCount} Artikel auf der Einkaufsliste fehlen noch.`}
        </p>
        <a href="/?tab=shopping" className="btn btn-secondary mt-auto">Zur Liste</a>
      </div>

      <div className="glass-panel p-8 flex flex-col gap-4">
        <div className="flex items-center gap-4 text-violet-500">
          <CheckSquare size={32} />
          <h2 className="text-2xl font-semibold m-0 text-slate-900 border-none">Putzplan</h2>
        </div>
        <p className="text-slate-600 leading-relaxed">
          {nextTodo 
            ? `${nextTodo.assignee} ist diese Woche mit "${nextTodo.title}" dran.`
            : "Keine offenen Aufgaben für diese Woche."}
        </p>
        <a href="/?tab=todos" className="btn btn-secondary mt-auto">Zum Plan</a>
      </div>

      <div className="glass-panel p-8 flex flex-col gap-4">
        <div className="flex items-center gap-4 text-emerald-500">
          <Wallet size={32} />
          <h2 className="text-2xl font-semibold m-0 text-slate-900 border-none">Finanzen</h2>
        </div>
        <p className="text-slate-600 leading-relaxed">{financesStatusText}</p>
        <a href="/?tab=finance" className="btn btn-secondary mt-auto">Zum Finanzcheck</a>
      </div>
    </div>
  );
}
